if (UnityEditor.AssetDatabase.IsValidFolder("Assets/Resources/Data/Items")) throw new System.Exception("Historical setup: content already migrated. Edit existing assets; do not recreate old folders.");
if(UnityEditor.EditorApplication.isPlaying)throw new System.Exception("Stop Play first");
var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.path!="Assets/Scenes/GameScane.unity")throw new System.Exception("Wrong scene");
if(UnityEditor.AssetDatabase.IsValidFolder("Assets/Resources/Data/ElementsV1"))throw new System.Exception("Element content already exists; inspect before running again");
UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene,"Backups/2026-10-09-elements/BeforeElements.unity",true);
var shop=UnityEngine.Object.FindObjectOfType<ShopManager>();var originals=new System.Collections.Generic.List<ItemData>(shop.allItems);if(originals.Count!=30)throw new System.Exception("Expected 30 source items");
UnityEditor.AssetDatabase.CreateFolder("Assets/Resources/Data","ElementsV1");
var ui=UnityEngine.Object.FindObjectOfType<UİManager>();var towerPrefabs=new[]{ui.ArcherTowerPrefab,ui.MegicTowerPrefab,ui.UnitTowerPrefab};
foreach(var prefab in towerPrefabs){var sourcePath=UnityEditor.AssetDatabase.GetAssetPath(prefab);System.IO.File.Copy(sourcePath,"Backups/2026-10-09-elements/"+System.IO.Path.GetFileName(sourcePath),true);var dataPath=UnityEditor.AssetDatabase.GetAssetPath(prefab.GetComponent<Tower>().data);System.IO.File.Copy(dataPath,"Backups/2026-10-09-elements/"+System.IO.Path.GetFileName(dataPath),true);}
var reports=new System.Collections.Generic.List<object>();
for(int number=1;number<=4;number++){
 var element=(ElementType)number;string label=UİManager.ElementLabel(element);string folder="Assets/Resources/Data/ElementsV1/"+element;UnityEditor.AssetDatabase.CreateFolder("Assets/Resources/Data/ElementsV1",element.ToString());
 var copies=new System.Collections.Generic.Dictionary<ItemData,ItemData>();
 foreach(var source in originals){var item=UnityEngine.Object.Instantiate(source);item.element=element;item.itemID=source.itemID+"_"+element.ToString().ToLowerInvariant();item.Name=label+" · "+source.Name;item.damageBonus=source.damageBonus+.05f;item.cost=UnityEngine.Mathf.CeilToInt(source.cost*1.1f/5f)*5;UnityEditor.AssetDatabase.CreateAsset(item,folder+"/"+item.itemID+".asset");copies.Add(source,item);shop.allItems.Add(item);}
 foreach(var pair in copies){foreach(var rule in pair.Value.synergyRules){if(rule!=null&&rule.acceptedItem!=null&&copies.ContainsKey(rule.acceptedItem))rule.acceptedItem=copies[rule.acceptedItem];}UnityEditor.EditorUtility.SetDirty(pair.Value);}
 foreach(var prefab in towerPrefabs){var td=prefab.GetComponent<Tower>().data;var main=UnityEngine.Object.Instantiate(td.defaultWeapon);main.element=element;main.itemID="main_"+td.type.ToString().ToLowerInvariant()+"_"+element.ToString().ToLowerInvariant();main.Name=label+(td.type==TowerType.MagicTower?" Asası":td.type==TowerType.ArrowTower?" Yayı":" Kılıcı");main.damageBonus=td.defaultWeapon.damageBonus+.1f;main.cost=0;UnityEditor.AssetDatabase.CreateAsset(main,folder+"/"+main.itemID+".asset");switch(element){case ElementType.Fire:td.fireWeapon=main;break;case ElementType.Water:td.waterWeapon=main;break;case ElementType.Earth:td.earthWeapon=main;break;case ElementType.Air:td.airWeapon=main;break;}UnityEditor.EditorUtility.SetDirty(td);}
 // Mevcut üç tarifin element karşılıkları: aynı bir-wave kuralı korunur.
 var recipes=new System.Collections.Generic.List<ItemEvolutionRecipe>();
 foreach(var id in UnityEditor.AssetDatabase.FindAssets("t:ItemEvolutionRecipe",new[]{"Assets/Resources/Data/Evolutions"})){var original=UnityEditor.AssetDatabase.LoadAssetAtPath<ItemEvolutionRecipe>(UnityEditor.AssetDatabase.GUIDToAssetPath(id));if(!copies.ContainsKey(original.first)||!copies.ContainsKey(original.second))continue;var result=UnityEngine.Object.Instantiate(original.result);result.element=element;result.itemID=original.result.itemID+"_"+element.ToString().ToLowerInvariant();result.Name=label+" · "+original.result.Name;result.damageBonus=original.result.damageBonus+.1f;result.cost=copies[original.first].cost+copies[original.second].cost;foreach(var rule in result.synergyRules)if(rule!=null&&rule.acceptedItem!=null&&copies.ContainsKey(rule.acceptedItem))rule.acceptedItem=copies[rule.acceptedItem];UnityEditor.AssetDatabase.CreateAsset(result,folder+"/"+result.itemID+".asset");var recipe=UnityEngine.ScriptableObject.CreateInstance<ItemEvolutionRecipe>();recipe.first=copies[original.first];recipe.second=copies[original.second];recipe.result=result;UnityEditor.AssetDatabase.CreateAsset(recipe,folder+"/recipe_"+result.itemID+".asset");recipes.Add(recipe);}
 foreach(var prefab in towerPrefabs){string path=UnityEditor.AssetDatabase.GetAssetPath(prefab);var root=UnityEditor.PrefabUtility.LoadPrefabContents(path);try{var tower=root.GetComponent<Tower>();foreach(var recipe in recipes)if(System.Array.Exists(recipe.first.itemOwners,x=>x==tower.data.type))tower.evolutionRecipes.Add(recipe);UnityEditor.PrefabUtility.SaveAsPrefabAsset(root,path);}finally{UnityEditor.PrefabUtility.UnloadPrefabContents(root);}}
 reports.Add(new{element=element.ToString(),shopItems=copies.Count,recipes=recipes.Count,mainItems=3});
}
ui.towerPanelTitle.resizeTextForBestFit=true;ui.towerPanelTitle.resizeTextMinSize=20;ui.towerPanelTitle.resizeTextMaxSize=27;
UnityEditor.EditorUtility.SetDirty(shop);UnityEditor.EditorUtility.SetDirty(ui);UnityEditor.AssetDatabase.SaveAssets();UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);
return new{shopItems=shop.allItems.Count,created=reports};
